import json,math
r=[x for x in json.load(open('data.json')) if x[3]>3]
def fit(z,f):
  n=len(z);mz=sum(z)/n;mf=sum(f)/n
  s=sum((a-mz)*(b-mf) for a,b in zip(z,f))/sum((a-mz)**2 for a in z)
  res=[b-mf-s*(a-mz) for a,b in zip(z,f)]
  return -s,max(map(abs,res))
