for name,f in (('Fz',[x[3] for x in r]),('|F|',[math.sqrt(x[1]**2+x[2]**2+x[3]**2) for x in r])):
  k,e=fit(z,f);print(name,k,e,1/(1/k-0.00817),1/(1/k-0.0012))
